<?php require_once 'includes.php';if(is_logged_in()){header('Location: profile.php');exit;}$errors=[];$name='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');if(strlen($name)<2||strlen($name)>100)$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(strlen($pw)<8)$errors[]='Password must be at least 8 characters.';if($pw!==$confirm)$errors[]='Passwords do not match.';if(!$errors){try{$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)db()->lastInsertId();$_SESSION['flash']='Welcome to Time to Trip!';header('Location: profile.php');exit;}catch(PDOException $x){$errors[]=$x->getCode()==='23000'?'That email already has an account.':'Could not create account. Check database setup.';}}}page_header('Create account');?><section class="form-layout"><div class="form-panel"><p class="eyebrow">YOUR NEXT CHAPTER</p><h1>Create your account</h1><p>Join travellers who believe the journey is better together.</p><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-field">Full name<input name="name" required minlength="2" maxlength="100" autocomplete="name" value="<?=e($name)?>"></label><label class="form-field">Email address<input name="email" type="email" required autocomplete="email" value="<?=e($email)?>"></label><label class="form-field">Password<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><label class="form-field">Confirm password<input name="confirm_password" type="password" required minlength="8" autocomplete="new-password"></label><button class="btn btn-primary full-width">Create account</button></form><p style="margin-top:18px">Already registered? <a class="text-link" href="signin.php">Sign in</a></p></div></section><?php page_footer();?>